#include <stdio.h>
#include <stdlib.h>

typedef struct {
    long long A, B, P, Q;
} Line;

typedef struct {
    long long P;
    int rank;
} Item;

int cmpLine(const void *a, const void *b) {
    const Line *x = (const Line*)a;
    const Line *y = (const Line*)b;
    if (x->A < y->A) return -1;
    if (x->A > y->A) return 1;
    if (x->B < y->B) return -1;
    if (x->B > y->B) return 1;
    return 0;
}

int cmpLL(const void *a, const void *b) {
    long long x = *(const long long*)a;
    long long y = *(const long long*)b;
    if (x < y) return -1;
    if (x > y) return 1;
    return 0;
}

int lowerBound(long long *arr, int n, long long val) {
    int lo = 0, hi = n;
    while (lo < hi) {
        int mid = (lo + hi) / 2;
        if (arr[mid] < val) lo = mid + 1;
        else hi = mid;
    }
    return lo;
}

#define MAXN 100005

Item a[MAXN], temp[MAXN];
int bit[MAXN];
int uniq_cnt;

void bitAdd(int idx, int val) {
    for (; idx <= uniq_cnt; idx += idx & -idx) {
        bit[idx] += val;
    }
}

int bitSum(int idx) {
    int s = 0;
    for (; idx > 0; idx -= idx & -idx) {
        s += bit[idx];
    }
    return s;
}

long long cdq(int l, int r) {
    if (l >= r) return 0;

    int mid = (l + r) / 2;
    long long ans = cdq(l, mid) + cdq(mid + 1, r);

    int ptr = l;
    for (int j = mid + 1; j <= r; j++) {
        while (ptr <= mid && a[ptr].P >= a[j].P) {
            bitAdd(a[ptr].rank, 1);
            ptr++;
        }
        ans += bitSum(a[j].rank);
    }

    for (int i = l; i < ptr; i++) {
        bitAdd(a[i].rank, -1);
    }

    int i = l, j = mid + 1, k = l;
    while (i <= mid && j <= r) {
        if (a[i].P >= a[j].P) {
            temp[k++] = a[i++];
        } else {
            temp[k++] = a[j++];
        }
    }
    while (i <= mid) temp[k++] = a[i++];
    while (j <= r) temp[k++] = a[j++];
    for (i = l; i <= r; i++) a[i] = temp[i];

    return ans;
}

int main() {
    int N;
    long long X1, X2;

    if (scanf("%d %lld %lld", &N, &X1, &X2) != 3) return 0;

    Line *lines = (Line*)malloc(N * sizeof(Line));
    long long *qs = (long long*)malloc(N * sizeof(long long));
    if (!lines || !qs) return 0;

    for (int i = 0; i < N; i++) {
        long long A, B;
        scanf("%lld %lld", &A, &B);
        lines[i].A = A;
        lines[i].B = B;
        lines[i].P = A * X1 + B;
        lines[i].Q = A * X2 + B;
    }

    qsort(lines, N, sizeof(Line), cmpLine);

    for (int i = 0; i < N; i++) {
        a[i].P = lines[i].P;
        qs[i] = lines[i].Q;
    }

    qsort(qs, N, sizeof(long long), cmpLL);

    uniq_cnt = 0;
    for (int i = 0; i < N; i++) {
        if (i == 0 || qs[i] != qs[uniq_cnt - 1]) {
            qs[uniq_cnt++] = qs[i];
        }
    }

    for (int i = 0; i < N; i++) {
        int idx = lowerBound(qs, uniq_cnt, lines[i].Q);
        a[i].rank = idx + 1;
    }

    long long ans = cdq(0, N - 1);
    printf("%lld\n", ans);

    free(lines);
    free(qs);
    return 0;
}
